<template><view :class="['app-page',{dark}]"><ui-header title="消息设置" back/><view class="notice-card" v-for="item in items" :key="item.key"><view class="notice-icon"><ui-icon :name="item.icon" :size="40"/></view><view class="notice-copy"><text>{{item.title}}</text><text>{{item.copy}}</text></view><switch :checked="settings[item.key]" color="#f0445a" @change="change(item.key,$event)"/></view><text v-if="error" class="error">{{error}}</text></view></template>
<script>import{isDark}from'@/utils/app';import{api}from'@/services/api';export default{data(){return{dark:false,error:'',settings:{orderEnabled:true,promotionEnabled:false,systemEnabled:true},items:[{key:'orderEnabled',title:'订单消息',copy:'接收订单状态和支付提醒',icon:'receipt-clock'},{key:'promotionEnabled',title:'活动消息',copy:'接收优惠和活动提醒',icon:'sparkles'},{key:'systemEnabled',title:'系统消息',copy:'接收审核及账户安全提醒',icon:'bell'}]}},onLoad(){this.dark=isDark();api.getNotificationSettings().then(data=>{this.settings={...this.settings,...data}}).catch(e=>{this.error=e.message})},methods:{async change(key,e){const previous=this.settings[key];this.settings[key]=e.detail.value;try{this.settings=await api.updateNotificationSettings(this.settings)}catch(error){this.settings[key]=previous;this.error=error.message||'保存失败'}}}}</script>
<style scoped>.notice-card{min-height:122rpx;margin:18rpx 28rpx;padding:20rpx 24rpx;display:flex;align-items:center;gap:18rpx;border-radius:24rpx;background:var(--surface);box-shadow:var(--shadow-card)}.notice-icon{width:72rpx;height:72rpx;display:flex;align-items:center;justify-content:center;border-radius:24rpx;background:var(--brand-soft)}.notice-copy{min-width:0;flex:1;display:flex;flex-direction:column;gap:8rpx}.notice-copy text:first-child{font-size:27rpx;font-weight:700}.notice-copy text:last-child{color:var(--muted);font-size:22rpx}.error{display:block;margin:20rpx 30rpx;color:var(--primary);font-size:22rpx}</style>
